function transform(ctx) {
  var u = ctx.vars.portal_url || "";
  if (!u || u.indexOf("?") < 0) throw new Error("未能获取门户跳转地址（Location），请核对本校门户地址后把地址写进本步骤脚本");
  var q = u.slice(u.indexOf("?") + 1);
  var host = u.split("/")[2];
  var MAP = {"校园网": "default", "移动": "cmcc", "联通": "unicom", "电信": "ctcc"};
  var isp = (ctx.isp || "").trim();
  var service = isp ? (MAP[isp] !== undefined ? MAP[isp] : isp) : "default";
  return { portal_host: host, qse: url_encode(url_encode(q)), eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode(service) }; // 原实现 NetworkAuth.py L23 先 quote(query)，requests data= 提交时再整体编码一次 => 双重编码
}
